create function pg_temp.c1d_publish_error_detail(target_detail_id uuid, target_expected_version bigint, target_idempotency_key uuid, target_request_id uuid) returns jsonb language plpgsql as $$
declare v_detail text;
begin
  perform public.c1_publish_project_cost_detail('c1d10000-0000-4000-8000-000000000020',target_detail_id,jsonb_build_object('expectedVersion',target_expected_version),target_idempotency_key,target_request_id);
  raise exception 'C1D expected publish readiness failure';
exception when others then
  get stacked diagnostics v_detail = pg_exception_detail;
  return coalesce(v_detail,'[]')::jsonb;
end;
$$;
